def check_one_term_solutions():
    limit = 4000
    solutions = []
    p = 2
    while True:
        try:
            n = p**p
        except OverflowError:
            # Should not happen for standard primes before the limit, but good practice
            break

        if n <= limit:
            solutions.append((p, n))
        else:
            break
        p += 1
    return solutions

solutions = check_one_term_solutions()
print("Solutions found (p, n):", solutions)
